<script setup lang="ts">
import { Head, Link, router, useForm, usePage } from '@inertiajs/vue3';
import { computed } from 'vue';
import FieldError from '../../../components/FieldError.vue';
import AdminLayout from '../../../layouts/AdminLayout.vue';
import type { PageProps } from '../../../types';

interface History { id: string; from_status: string | null; to_status: string; reason: string | null; actor: string | null; created_at: string }
interface FulfillmentItem { id: string; product_name: string; variant_name: string | null; sku: string; quantity: number; inventory_reservation_id: string }
interface Shipment { id: string; status: string; carrier: string | null; carrier_name: string | null; service_name: string | null; tracking_number: string | null; tracking_url: string | null; ready_at: string | null; shipped_at: string | null; delivered_at: string | null; can_ready: boolean; can_ship: boolean; can_deliver: boolean; can_cancel: boolean; history: History[] }
interface Fulfillment { id: string; order_id: string; order_number: string; status: string; location_name: string; location_code: string; items: FulfillmentItem[]; history: History[]; shipments: Shipment[]; started_at: string | null; completed_at: string | null; cancelled_at: string | null; created_at: string }
interface Capabilities { manage: boolean; complete: boolean; shipments_manage: boolean; start: boolean; cancel: boolean; create_shipment: boolean; complete_action: boolean }
interface Eligibility { eligible: boolean; reason: string | null }
const props = defineProps<{ fulfillment: Fulfillment; capabilities: Capabilities; paymentEligibility: Eligibility }>();
const page = usePage<PageProps>();
const statusNotice = computed(() => page.props.status);
const errors = computed(() => page.props.errors as Record<string, string | undefined>);
const fulfillmentCancelForm = useForm({ reason: '' });
const shipmentForm = useForm({ carrier_name: '', service_name: '', tracking_number: '', tracking_url: '' });
const post = (suffix: string) => router.post(`/admin/fulfillments/${props.fulfillment.id}/${suffix}`, {}, { preserveScroll: true });
const cancelFulfillment = () => { if (window.confirm('Cancel this fulfillment and release its remaining work?')) fulfillmentCancelForm.post(`/admin/fulfillments/${props.fulfillment.id}/cancel`, { preserveScroll: true }); };
const createShipment = () => shipmentForm.post(`/admin/fulfillments/${props.fulfillment.id}/shipment`, { preserveScroll: true, onSuccess: () => shipmentForm.reset() });
const shipmentAction = (shipment: Shipment, action: string) => router.post(`/admin/shipments/${shipment.id}/${action}`, {}, { preserveScroll: true });
const cancelShipment = (shipment: Shipment) => {
    const reason = window.prompt('Why is this shipment being cancelled?');
    if (reason?.trim()) router.post(`/admin/shipments/${shipment.id}/cancel`, { reason: reason.trim() }, { preserveScroll: true });
};
</script>

<template>
    <Head :title="`Fulfillment ${fulfillment.order_number}`" />
    <AdminLayout><section>
        <div class="flex flex-wrap items-end justify-between gap-5"><div><Link href="/admin/fulfillments" class="text-sm font-semibold text-emerald-800">Back to fulfillments</Link><p class="mt-7 font-mono text-xs tracking-[0.2em] text-emerald-800 uppercase">{{ fulfillment.location_code }} / {{ fulfillment.status }}</p><h1 class="mt-3 text-4xl font-semibold tracking-[-0.04em] sm:text-6xl">{{ fulfillment.order_number }}</h1><p class="mt-3 break-all font-mono text-xs text-[#637067]">{{ fulfillment.id }}</p></div><Link :href="`/admin/orders/${fulfillment.order_id}`" class="border border-[#17211b] px-4 py-3 text-sm font-semibold">Open order</Link></div>
        <p v-if="statusNotice" class="mt-6 border border-emerald-700 bg-emerald-50 p-4 text-sm font-semibold text-emerald-900">{{ statusNotice }}</p>

        <div class="mt-8 grid gap-4 sm:grid-cols-3"><article class="border bg-white p-5"><p class="text-xs uppercase text-[#637067]">Location</p><p class="mt-2 font-semibold">{{ fulfillment.location_name }}</p></article><article class="border bg-white p-5"><p class="text-xs uppercase text-[#637067]">Units</p><p class="mt-2 font-mono text-xl font-semibold">{{ fulfillment.items.reduce((total, item) => total + item.quantity, 0) }}</p></article><article :class="['border p-5', paymentEligibility.eligible ? 'border-emerald-700 bg-emerald-50' : 'border-amber-700 bg-amber-50']"><p class="text-xs uppercase text-[#637067]">Payment gate</p><p class="mt-2 font-semibold">{{ paymentEligibility.eligible ? 'Eligible' : 'Blocked' }}</p><p v-if="paymentEligibility.reason" class="mt-1 text-sm">{{ paymentEligibility.reason }}</p></article></div>

        <div v-if="capabilities.start || capabilities.complete_action || capabilities.cancel" class="mt-6 flex flex-wrap gap-3"><button v-if="capabilities.start" class="bg-[#17211b] px-5 py-3 text-sm font-semibold text-white" @click="post('start')">Start picking</button><button v-if="capabilities.complete_action" :disabled="!paymentEligibility.eligible" class="border border-emerald-800 px-5 py-3 text-sm font-semibold text-emerald-900 disabled:cursor-not-allowed disabled:opacity-40" @click="post('complete')">Complete fulfillment</button></div>

        <section class="mt-10 grid gap-6 lg:grid-cols-[3fr_2fr]"><div><h2 class="text-3xl font-semibold">Pick list</h2><div class="mt-5 overflow-x-auto border bg-white"><table class="min-w-full text-left text-sm"><thead class="bg-[#17211b] text-white"><tr><th class="p-4">Item</th><th class="p-4">SKU</th><th class="p-4">Quantity</th></tr></thead><tbody><tr v-for="item in fulfillment.items" :key="item.id" class="border-t"><td class="p-4 font-semibold">{{ item.product_name }}<br><span class="font-normal text-[#637067]">{{ item.variant_name ?? 'Default variant' }}</span></td><td class="p-4 font-mono">{{ item.sku }}</td><td class="p-4 font-mono text-lg">{{ item.quantity }}</td></tr></tbody></table></div></div><div><h2 class="text-3xl font-semibold">History</h2><ol class="mt-5 space-y-4"><li v-for="entry in fulfillment.history" :key="entry.id" class="border-l-2 border-emerald-700 pl-4"><p class="font-mono text-sm font-semibold">{{ entry.from_status ?? 'CREATED' }} → {{ entry.to_status }}</p><p class="mt-1 text-xs text-[#637067]">{{ new Date(entry.created_at).toLocaleString() }} / {{ entry.actor ?? 'System' }}</p><p v-if="entry.reason" class="mt-1 text-sm">{{ entry.reason }}</p></li></ol></div></section>

        <aside class="mt-6 border border-[#17211b]/15 bg-white p-4"><p class="text-xs font-semibold uppercase text-[#637067]">Reservation traceability</p><ul class="mt-2 grid gap-1 font-mono text-xs"><li v-for="item in fulfillment.items" :key="`reservation-${item.id}`">{{ item.sku }} / {{ item.inventory_reservation_id }} / qty {{ item.quantity }}</li></ul></aside>

        <section class="mt-12"><div class="flex flex-wrap items-end justify-between gap-3"><div><p class="font-mono text-xs tracking-[0.2em] text-emerald-800 uppercase">Dispatch</p><h2 class="mt-2 text-3xl font-semibold">Shipments</h2></div></div>
            <form v-if="capabilities.create_shipment" class="mt-5 grid gap-4 border border-[#17211b]/20 bg-[#f8f5ed] p-5 sm:grid-cols-2" @submit.prevent="createShipment"><label class="text-sm font-semibold">Carrier<input v-model="shipmentForm.carrier_name" maxlength="120" class="mt-2 w-full border bg-white px-3 py-2 font-normal" /></label><label class="text-sm font-semibold">Service<input v-model="shipmentForm.service_name" maxlength="120" class="mt-2 w-full border bg-white px-3 py-2 font-normal" /></label><label class="text-sm font-semibold">Tracking number<input v-model="shipmentForm.tracking_number" maxlength="160" class="mt-2 w-full border bg-white px-3 py-2 font-normal" /></label><label class="text-sm font-semibold">Tracking URL<input v-model="shipmentForm.tracking_url" type="url" maxlength="2048" class="mt-2 w-full border bg-white px-3 py-2 font-normal" /></label><div class="sm:col-span-2"><FieldError :message="shipmentForm.errors.carrier_name ?? shipmentForm.errors.service_name ?? shipmentForm.errors.tracking_number ?? shipmentForm.errors.tracking_url ?? errors.shipment" /><button :disabled="shipmentForm.processing" class="mt-2 bg-[#17211b] px-5 py-3 text-sm font-semibold text-white disabled:opacity-40">Create shipment</button></div></form>
            <div class="mt-5 grid gap-5"><article v-for="shipment in fulfillment.shipments" :key="shipment.id" class="border border-[#17211b]/15 bg-white p-5"><div class="flex flex-wrap items-start justify-between gap-4"><div><p class="font-mono text-xs text-[#637067]">{{ shipment.id }}</p><p class="mt-2 text-xl font-semibold">{{ shipment.carrier ?? 'Manual shipment' }}</p><p class="mt-1 font-mono text-sm">{{ shipment.tracking_number ?? 'No tracking number' }}</p><a v-if="shipment.tracking_url" :href="shipment.tracking_url" target="_blank" rel="noopener noreferrer" class="mt-2 inline-block text-sm font-semibold text-emerald-800">Open tracking</a></div><span class="bg-[#17211b] px-3 py-2 font-mono text-xs text-white">{{ shipment.status }}</span></div><div class="mt-4 flex flex-wrap gap-2"><button v-if="shipment.can_ready" class="border px-3 py-2 text-sm font-semibold" @click="shipmentAction(shipment, 'ready')">Mark ready</button><button v-if="shipment.can_ship" class="border border-emerald-800 px-3 py-2 text-sm font-semibold text-emerald-900" @click="shipmentAction(shipment, 'ship')">Mark shipped</button><button v-if="shipment.can_deliver" class="bg-emerald-800 px-3 py-2 text-sm font-semibold text-white" @click="shipmentAction(shipment, 'deliver')">Mark delivered</button><button v-if="shipment.can_cancel" class="border border-red-800 px-3 py-2 text-sm font-semibold text-red-900" @click="cancelShipment(shipment)">Cancel shipment</button></div><ol v-if="shipment.history.length" class="mt-5 grid gap-2 border-t pt-4 text-xs text-[#637067]"><li v-for="entry in shipment.history" :key="entry.id"><span class="font-mono font-semibold text-[#17211b]">{{ entry.from_status ?? 'CREATED' }} → {{ entry.to_status }}</span> / {{ new Date(entry.created_at).toLocaleString() }} / {{ entry.actor ?? 'System' }}<template v-if="entry.reason"> / {{ entry.reason }}</template></li></ol></article><p v-if="!fulfillment.shipments.length" class="border border-dashed p-8 text-center text-[#637067]">No shipment has been created.</p></div>
        </section>

        <form v-if="capabilities.cancel" class="mt-12 border border-red-800/30 bg-red-50 p-6" @submit.prevent="cancelFulfillment"><h2 class="text-2xl font-semibold text-red-900">Cancel fulfillment</h2><label class="mt-4 block text-sm font-semibold">Reason<textarea v-model="fulfillmentCancelForm.reason" required maxlength="500" class="mt-2 min-h-24 w-full border border-red-800/40 bg-white px-3 py-2" /></label><FieldError :message="fulfillmentCancelForm.errors.reason ?? errors.fulfillment" /><button :disabled="fulfillmentCancelForm.processing" class="mt-4 border border-red-900 px-5 py-3 text-sm font-semibold text-red-900">Cancel fulfillment</button></form>
        <div v-if="errors.shipment" class="mt-5 border border-red-700 bg-red-50 p-4"><FieldError :message="errors.shipment" /></div>
    </section></AdminLayout>
</template>
